        {/* Generic Notes for logins/cards */}
        {item.category !== 'notes' && item.notes && (
          <div style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', borderTop: '1px dashed var(--border-color)', paddingTop: '0.35rem', marginTop: '0.2rem' }}>
            <span style={{ color: 'var(--text-muted)' }}>Note: </span>
            {item.notes}
          </div>
        )}
      </div>

      <div className="item-card-footer">
        <span>Updated: {item.updatedAt ? new Date(item.updatedAt).toLocaleDateString() : 'Just now'}</span>
        {item.category !== 'notes' && (
          <span style={{ textTransform: 'capitalize', color: 'var(--text-secondary)' }}>
            {item.category}
          </span>
        )}
      </div>
    </div>
  );
}

import React, { useMemo } from 'react';
import { ItemCard } from './ItemCard';
import { Key, Plus, Search } from './Icons';

export function ItemList({
  items,
  activeCategory,
  searchQuery,
  onOpenAddModal,
  onEditItem
}) {
  const filteredItems = useMemo(() => {
    return items.filter((item) => {
      // Category filter
      if (activeCategory === 'favorites') {
        if (!item.favorite) return false;
      } else if (activeCategory !== 'all') {
        if (item.category !== activeCategory) return false;
      }

      // Search filter
      if (searchQuery.trim()) {
        const query = searchQuery.toLowerCase();
        const titleMatch = item.title?.toLowerCase().includes(query);
        const userMatch = item.username?.toLowerCase().includes(query);
        const urlMatch = item.url?.toLowerCase().includes(query);
        const notesMatch = item.notes?.toLowerCase().includes(query);
        const cardMatch = item.cardholder?.toLowerCase().includes(query);
        return titleMatch || userMatch || urlMatch || notesMatch || cardMatch;
      }

      return true;
    });
  }, [items, activeCategory, searchQuery]);

  const getCategoryTitle = () => {
    switch (activeCategory) {
      case 'favorites':
        return 'Favorite Credentials';
      case 'logins':
        return 'Logins & Passwords';
      case 'cards':
        return 'Payment Cards';
      case 'notes':
        return 'Secure Notes';
      default:
        return 'All Vault Items';
    }
  };

  return (
    <div className="content-area">
      <div className="content-header">
        <div>
          <h2 className="content-title">{getCategoryTitle()}</h2>
          <p style={{ color: 'var(--text-muted)', fontSize: '0.85rem' }}>
            {filteredItems.length} {filteredItems.length === 1 ? 'item' : 'items'} found
            {searchQuery && ` matching "${searchQuery}"`}
          </p>
        </div>

        <button className="btn btn-primary" onClick={onOpenAddModal}>
          <Plus size={16} />
          <span>Add New</span>
        </button>
      </div>

      {filteredItems.length === 0 ? (
        <div className="empty-state">
          <div className="empty-icon">
            {searchQuery ? <Search size={28} /> : <Key size={28} />}
          </div>
          <div>
            <h3 style={{ fontSize: '1.1rem', fontWeight: 600, color: 'var(--text-primary)', marginBottom: '0.25rem' }}>
              {searchQuery ? 'No matching items found' : 'No items in this category'}
            </h3>
            <p style={{ fontSize: '0.9rem', color: 'var(--text-secondary)' }}>
              {searchQuery
                ? 'Try refining your search term or clear the search field.'
                : 'Start organizing your sensitive data securely in this offline vault.'}
            </p>
          </div>
          {!searchQuery && (
            <button className="btn btn-primary" onClick={onOpenAddModal} style={{ marginTop: '0.5rem' }}>
              <Plus size={16} /> Add Your First Item
            </button>
          )}
        </div>
      ) : (
        <div className="items-grid">
          {filteredItems.map((item) => (
            <ItemCard key={item.id} item={item} onEdit={onEditItem} />
          ))}
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useVault } from '../context/VaultContext';
import { useToast } from './Toast';
import { X, Globe, CreditCard, FileText, Sparkles, Eye, EyeOff, Star } from './Icons';
import { generateSecurePassword, evaluatePasswordStrength } from '../services/generator';

export function ItemModal({ isOpen, onClose, editingItem }) {
  const { addItem, updateItem } = useVault();
  const { showToast } = useToast();

  const [category, setCategory] = useState('logins');
  const [title, setTitle] = useState('');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [url, setUrl] = useState('');
  const [cardholder, setCardholder] = useState('');
  const [cardNumber, setCardNumber] = useState('');
  const [expiry, setExpiry] = useState('');
  const [cvv, setCvv] = useState('');
  const [notes, setNotes] = useState('');
  const [favorite, setFavorite] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    if (editingItem) {
      setCategory(editingItem.category || 'logins');
      setTitle(editingItem.title || '');
      setUsername(editingItem.username || '');
      setPassword(editingItem.password || '');
      setUrl(editingItem.url || '');
      setCardholder(editingItem.cardholder || '');
      setCardNumber(editingItem.cardNumber || '');
      setExpiry(editingItem.expiry || '');
      setCvv(editingItem.cvv || '');
      setNotes(editingItem.notes || '');
      setFavorite(!!editingItem.favorite);
    } else {
      setCategory('logins');
      setTitle('');
      setUsername('');
      setPassword('');
      setUrl('');
      setCardholder('');
      setCardNumber('');
      setExpiry('');
      setCvv('');
      setNotes('');
      setFavorite(false);
    }
  }, [editingItem, isOpen]);

  if (!isOpen) return null;

  const handleQuickGenerate = () => {
    const generated = generateSecurePassword({ length: 20 });
    setPassword(generated);
    setShowPassword(true);
    showToast('Generated strong 20-character password');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!title.trim()) {
      showToast('Please enter a title', 'danger');
      return;
    }

    setIsSubmitting(true);
    try {
      const itemData = {
        category,
        title: title.trim(),
        favorite,
        notes: notes.trim()
      };

      if (category === 'logins') {
        itemData.username = username.trim();
        itemData.password = password;
        itemData.url = url.trim();
      } else if (category === 'cards') {
        itemData.cardholder = cardholder.trim();
        itemData.cardNumber = cardNumber.trim();
        itemData.expiry = expiry.trim();
        itemData.cvv = cvv.trim();
      }

      if (editingItem) {
        await updateItem(editingItem.id, itemData);
        showToast('Item updated successfully');
      } else {
        await addItem(itemData);
        showToast('Item created and encrypted');
      }
      onClose();
    } catch (err) {
      showToast('Failed to save: ' + err.message, 'danger');
    } finally {
      setIsSubmitting(false);
    }
  };

  const strength = evaluatePasswordStrength(password);

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-card" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <div className="modal-title">
            {editingItem ? 'Edit Item' : 'New Vault Item'}
          </div>
          <button className="btn-icon" onClick={onClose}>
            <X size={18} />
          </button>
        </div>

        <form onSubmit={handleSubmit}>
          <div className="modal-body">
            {/* Category tabs */}
            {!editingItem && (
              <div style={{ display: 'flex', gap: '0.5rem', background: 'var(--bg-input)', padding: '0.25rem', borderRadius: 'var(--radius-md)' }}>
                {[
                  { id: 'logins', label: 'Login', icon: Globe },
                  { id: 'cards', label: 'Card', icon: CreditCard },
                  { id: 'notes', label: 'Note', icon: FileText }
                ].map((tab) => {
                  const Icon = tab.icon;
                  return (
                    <button
                      key={tab.id}
                      type="button"
                      className={`btn ${category === tab.id ? 'btn-primary' : 'btn-secondary'}`}
                      style={{ flex: 1, padding: '0.45rem', fontSize: '0.85rem' }}
                      onClick={() => setCategory(tab.id)}
                    >
                      <Icon size={16} /> {tab.label}
                    </button>
                  );
                })}
              </div>
            )}

            {/* Title */}
            <div className="form-group">
              <label className="form-label">Title / Service Name *</label>
              <div style={{ display: 'flex', gap: '0.5rem' }}>
                <input
                  type="text"
                  className="form-input"
                  placeholder="e.g. GitHub, Google, Wi-Fi router"
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  required
                  autoFocus
                />
                <button
                  type="button"
                  className="btn-icon"
                  style={{
                    color: favorite ? 'var(--warning)' : 'var(--text-muted)',
                    background: 'var(--bg-input)',
                    border: '1px solid var(--border-color)'
                  }}
                  onClick={() => setFavorite(!favorite)}
                  title={favorite ? 'Favorited' : 'Add to Favorites'}
                >
                  <Star size={18} filled={favorite} />
                </button>
              </div>
            </div>

            {/* Logins Fields */}
            {category === 'logins' && (
              <>
                <div className="form-group">
                  <label className="form-label">Username / Email</label>
                  <input
                    type="text"
                    className="form-input"
                    placeholder="user@example.com"
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                  />
                </div>

                <div className="form-group">
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <label className="form-label">Password</label>
                    <button
                      type="button"
                      onClick={handleQuickGenerate}
                      style={{
                        background: 'transparent',
                        border: 'none',
                        color: 'var(--primary)',
                        fontSize: '0.8rem',
                        display: 'flex',
                        alignItems: 'center',
                        gap: '4px',
                        cursor: 'pointer',
                        padding: '2px 6px'
                      }}
                    >
                      <Sparkles size={14} /> Generate Strong
                    </button>
                  </div>
                  <div className="input-with-action">
                    <input
                      type={showPassword ? 'text' : 'password'}
                      className="form-input"
                      placeholder="Enter or generate password"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                    />
                    <div className="input-action-buttons">
                      <button
                        type="button"
                        className="btn-icon"
                        onClick={() => setShowPassword(!showPassword)}
                      >
                        {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
                      </button>
                    </div>
                  </div>

                  {password && (
                    <div style={{ marginTop: '0.25rem' }}>
                      <div className="strength-meter">
                        <div className={`strength-bar ${strength.score >= 1 ? (strength.score === 1 ? 'weak' : strength.score === 2 ? 'medium' : 'strong') : ''}`} />
                        <div className={`strength-bar ${strength.score >= 2 ? (strength.score === 2 ? 'medium' : 'strong') : ''}`} />
                        <div className={`strength-bar ${strength.score >= 3 ? 'strong' : ''}`} />
                        <div className={`strength-bar ${strength.score >= 4 ? 'strong' : ''}`} />
                      </div>
                      <div className="strength-text" style={{ color: strength.color }}>
                        {strength.label} ({strength.bits} bits)
                      </div>
                    </div>
                  )}
                </div>

                <div className="form-group">
                  <label className="form-label">Website URL</label>
                  <input
                    type="text"
                    className="form-input"
                    placeholder="https://example.com"
                    value={url}
                    onChange={(e) => setUrl(e.target.value)}
                  />
                </div>
              </>
            )}

            {/* Cards Fields */}
            {category === 'cards' && (
              <>
                <div className="form-group">
                  <label className="form-label">Cardholder Name</label>
                  <input
                    type="text"
                    className="form-input"
                    placeholder="John Doe"
                    value={cardholder}
                    onChange={(e) => setCardholder(e.target.value)}
                  />
                </div>

                <div className="form-group">
                  <label className="form-label">Card Number</label>
                  <input
                    type="text"
                    className="form-input"
                    placeholder="4000 1234 5678 9010"
                    value={cardNumber}
                    onChange={(e) => setCardNumber(e.target.value)}
                  />
                </div>

                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.75rem' }}>
                  <div className="form-group">
                    <label className="form-label">Expires (MM/YY)</label>
                    <input
                      type="text"
                      className="form-input"
                      placeholder="12/28"
                      value={expiry}
                      onChange={(e) => setExpiry(e.target.value)}
                    />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Security Code (CVV)</label>
                    <input
                      type="password"
                      className="form-input"
                      placeholder="123"
                      maxLength={4}
                      value={cvv}
                      onChange={(e) => setCvv(e.target.value)}
                    />
                  </div>
                </div>
              </>
            )}

            {/* Notes / Secret content */}
            <div className="form-group">
              <label className="form-label">
                {category === 'notes' ? 'Secret Notes Content *' : 'Additional Notes (Encrypted)'}
              </label>
              <textarea
                className="form-textarea"
                rows={category === 'notes' ? 6 : 3}
                placeholder={category === 'notes' ? 'Type sensitive notes, recovery keys, recovery phrases...' : 'Optional private notes...'}
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
              />
            </div>
          </div>

          <div className="modal-footer">
            <button type="button" className="btn btn-secondary" onClick={onClose} disabled={isSubmitting}>
              Cancel
            </button>
            <button type="submit" className="btn btn-primary" disabled={isSubmitting}>
              {isSubmitting ? 'Encrypting...' : editingItem ? 'Save Changes' : 'Encrypt & Save'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import { useToast } from './Toast';
import { X, Copy, RefreshCw, Sparkles } from './Icons';
import { generateSecurePassword, evaluatePasswordStrength } from '../services/generator';

export function PasswordGeneratorModal({ isOpen, onClose }) {
  const { showToast } = useToast();

  const [length, setLength] = useState(20);
  const [useLower, setUseLower] = useState(true);
  const [useUpper, setUseUpper] = useState(true);
  const [useNumbers, setUseNumbers] = useState(true);
  const [useSymbols, setUseSymbols] = useState(true);
  const [avoidAmbiguous, setAvoidAmbiguous] = useState(false);
  const [generatedPassword, setGeneratedPassword] = useState('');

  const regenerate = useCallback(() => {
    const pwd = generateSecurePassword({
      length,
      useLower,
      useUpper,
      useNumbers,
      useSymbols,
      avoidAmbiguous
    });
    setGeneratedPassword(pwd);
  }, [length, useLower, useUpper, useNumbers, useSymbols, avoidAmbiguous]);

  useEffect(() => {
    if (isOpen) {
      regenerate();
    }
  }, [isOpen, regenerate]);

  if (!isOpen) return null;

  const copyPassword = () => {
    if (!generatedPassword) return;
    navigator.clipboard.writeText(generatedPassword);
    showToast('Password copied to clipboard!');
  };

  const strength = evaluatePasswordStrength(generatedPassword);

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-card" onClick={(e) => e.stopPropagation()} style={{ maxWidth: '480px' }}>
        <div className="modal-header">
          <div className="modal-title">
            <Sparkles size={20} style={{ color: 'var(--primary)' }} />
            <span>Password Generator</span>
          </div>
          <button className="btn-icon" onClick={onClose}>
            <X size={18} />
          </button>
        </div>

        <div className="modal-body">
          {/* Password Display Box */}
          <div
            style={{
              background: 'var(--bg-input)',
              border: '1px solid var(--border-color)',
              borderRadius: 'var(--radius-md)',
              padding: '1rem',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              gap: '0.75rem'
            }}
          >
            <span
              style={{
                fontFamily: 'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace',
                fontSize: '1.2rem',
                wordBreak: 'break-all',
                color: 'var(--text-primary)',
                letterSpacing: '1px'
              }}
            >
              {generatedPassword}
            </span>

            <div style={{ display: 'flex', gap: '0.25rem', flexShrink: 0 }}>
              <button
                type="button"
                className="btn-icon"
                onClick={regenerate}
                title="Generate new password"
              >
                <RefreshCw size={18} />
              </button>
              <button
                type="button"
                className="btn-icon"
                onClick={copyPassword}
                title="Copy to clipboard"
                style={{ color: 'var(--primary)' }}
              >
                <Copy size={18} />
              </button>
            </div>
          </div>

          {/* Strength Meter */}
          <div>
            <div className="strength-meter">
              <div className={`strength-bar ${strength.score >= 1 ? (strength.score === 1 ? 'weak' : strength.score === 2 ? 'medium' : 'strong') : ''}`} />
              <div className={`strength-bar ${strength.score >= 2 ? (strength.score === 2 ? 'medium' : 'strong') : ''}`} />
              <div className={`strength-bar ${strength.score >= 3 ? 'strong' : ''}`} />
              <div className={`strength-bar ${strength.score >= 4 ? 'strong' : ''}`} />
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '0.25rem' }}>
              <span className="strength-text" style={{ color: strength.color }}>
                {strength.label}
              </span>
              <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>
                ~{strength.bits} bits of entropy
              </span>
            </div>
          </div>

          {/* Length Slider */}
          <div className="form-group">
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <label className="form-label">Password Length</label>
              <span style={{ fontWeight: 600, color: 'var(--primary)' }}>{length}</span>
            </div>
            <input
              type="range"
              min="8"
              max="64"
              value={length}
              onChange={(e) => setLength(parseInt(e.target.value, 10))}
              style={{ width: '100%', accentColor: 'var(--primary)', cursor: 'pointer' }}
            />
          </div>

          {/* Character Options */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: '0.65rem' }}>
            <label style={{ display: 'flex', alignItems: 'center', gap: '0.6rem', fontSize: '0.9rem', cursor: 'pointer' }}>
              <input
                type="checkbox"
                checked={useUpper}
                onChange={(e) => setUseUpper(e.target.checked)}
                style={{ accentColor: 'var(--primary)' }}
              />
              <span>Uppercase Letters (A-Z)</span>
            </label>

            <label style={{ display: 'flex', alignItems: 'center', gap: '0.6rem', fontSize: '0.9rem', cursor: 'pointer' }}>
              <input
                type="checkbox"
                checked={useLower}
                onChange={(e) => setUseLower(e.target.checked)}
                style={{ accentColor: 'var(--primary)' }}
              />
              <span>Lowercase Letters (a-z)</span>
            </label>

            <label style={{ display: 'flex', alignItems: 'center', gap: '0.6rem', fontSize: '0.9rem', cursor: 'pointer' }}>
              <input
                type="checkbox"
                checked={useNumbers}
                onChange={(e) => setUseNumbers(e.target.checked)}
                style={{ accentColor: 'var(--primary)' }}
              />
              <span>Numbers (0-9)</span>
            </label>

            <label style={{ display: 'flex', alignItems: 'center', gap: '0.6rem', fontSize: '0.9rem', cursor: 'pointer' }}>
              <input
                type="checkbox"
                checked={useSymbols}
                onChange={(e) => setUseSymbols(e.target.checked)}
                style={{ accentColor: 'var(--primary)' }}
              />
              <span>Special Symbols (!@#$%^&*)</span>
            </label>

            <label style={{ display: 'flex', alignItems: 'center', gap: '0.6rem', fontSize: '0.9rem', cursor: 'pointer' }}>
              <input
                type="checkbox"
                checked={avoidAmbiguous}
                onChange={(e) => setAvoidAmbiguous(e.target.checked)}
                style={{ accentColor: 'var(--primary)' }}
              />
              <span>Avoid Ambiguous Characters (e.g. 1, l, I, 0, O)</span>
            </label>
          </div>
        </div>

        <div className="modal-footer">
          <button type="button" className="btn btn-secondary" onClick={onClose}>
            Done
          </button>
          <button type="button" className="btn btn-primary" onClick={copyPassword}>
            <Copy size={16} /> Copy Password
          </button>
        </div>
      </div>
    </div>
  );
}

import React, { useMemo } from 'react';
import { X, ShieldAlert, AlertTriangle, Check, Edit, Key } from './Icons';

export function SecurityAuditModal({ isOpen, onClose, items, onEditItem }) {
  const auditResults = useMemo(() => {
    const weakItems = [];
    const passwordGroups = {}; // password -> [items]
    let totalPasswords = 0;

    items.forEach((item) => {
      if (item.category === 'logins' && item.password) {
        totalPasswords++;
        // Weak check
        if (item.password.length < 12) {
          weakItems.push({ item, reason: `Too short (${item.password.length} chars, recommended 14+)` });
        }

        // Reused check
        if (!passwordGroups[item.password]) {
          passwordGroups[item.password] = [];
        }
        passwordGroups[item.password].push(item);
      }
    });

    const reusedGroups = Object.values(passwordGroups).filter((group) => group.length > 1);

    return {
      totalPasswords,
      weakItems,
      reusedGroups,
      isHealthy: weakItems.length === 0 && reusedGroups.length === 0
    };
  }, [items]);

  if (!isOpen) return null;

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-card" onClick={(e) => e.stopPropagation()} style={{ maxWidth: '600px' }}>
        <div className="modal-header">
          <div className="modal-title">
            <ShieldAlert size={20} style={{ color: auditResults.isHealthy ? 'var(--primary)' : 'var(--warning)' }} />
            <span>Vault Security Health Audit</span>
          </div>
          <button className="btn-icon" onClick={onClose}>
            <X size={18} />
          </button>
        </div>

        <div className="modal-body">
          {/* Stats Bar */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '0.75rem' }}>
            <div style={{ background: 'var(--bg-input)', padding: '0.85rem', borderRadius: 'var(--radius-md)', textAlign: 'center' }}>
              <div style={{ fontSize: '1.4rem', fontWeight: 700, color: 'var(--text-primary)' }}>
                {auditResults.totalPasswords}
              </div>
              <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>Total Logins</div>
            </div>

            <div style={{ background: 'var(--bg-input)', padding: '0.85rem', borderRadius: 'var(--radius-md)', textAlign: 'center' }}>
              <div style={{ fontSize: '1.4rem', fontWeight: 700, color: auditResults.weakItems.length > 0 ? 'var(--danger)' : 'var(--primary)' }}>
                {auditResults.weakItems.length}
              </div>
              <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>Weak Passwords</div>
            </div>

            <div style={{ background: 'var(--bg-input)', padding: '0.85rem', borderRadius: 'var(--radius-md)', textAlign: 'center' }}>
              <div style={{ fontSize: '1.4rem', fontWeight: 700, color: auditResults.reusedGroups.length > 0 ? 'var(--warning)' : 'var(--primary)' }}>
                {auditResults.reusedGroups.length}
              </div>
              <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>Reused Groups</div>
            </div>
          </div>

          {auditResults.isHealthy ? (
            <div
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: '0.75rem',
                background: 'rgba(16, 185, 129, 0.1)',
                border: '1px solid var(--primary)',
                padding: '1rem',
                borderRadius: 'var(--radius-md)',
                color: 'var(--primary)'
              }}
            >
              <Check size={24} />
              <div>
                <div style={{ fontWeight: 600 }}>All Passwords Look Strong!</div>
                <div style={{ fontSize: '0.85rem', color: 'var(--text-secondary)' }}>
                  No weak or duplicate passwords detected across your login credentials.
                </div>
              </div>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
              {/* Weak Passwords List */}
              {auditResults.weakItems.length > 0 && (
                <div>
                  <h4 style={{ fontSize: '0.9rem', color: 'var(--danger)', marginBottom: '0.5rem', display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
                    <AlertTriangle size={16} /> Weak Passwords ({auditResults.weakItems.length})
                  </h4>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                    {auditResults.weakItems.map(({ item, reason }) => (
                      <div
                        key={item.id}
                        style={{
                          background: 'var(--bg-input)',
                          border: '1px solid var(--border-color)',
                          borderRadius: 'var(--radius-md)',
                          padding: '0.65rem 0.85rem',
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'space-between'
                        }}
                      >
                        <div>
                          <div style={{ fontWeight: 600, fontSize: '0.9rem' }}>{item.title}</div>
                          <div style={{ fontSize: '0.78rem', color: 'var(--danger)' }}>{reason}</div>
                        </div>
                        <button
                          className="btn btn-secondary"
                          style={{ padding: '0.35rem 0.65rem', fontSize: '0.8rem' }}
                          onClick={() => {
                            onClose();
                            onEditItem(item);
                          }}
                        >
                          <Edit size={14} /> Update
                        </button>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Reused Passwords List */}
              {auditResults.reusedGroups.length > 0 && (
                <div>
                  <h4 style={{ fontSize: '0.9rem', color: 'var(--warning)', marginBottom: '0.5rem', display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
                    <AlertTriangle size={16} /> Reused Passwords Across Accounts
                  </h4>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                    {auditResults.reusedGroups.map((group, idx) => (
                      <div
                        key={idx}
                        style={{
                          background: 'var(--bg-input)',
                          border: '1px solid rgba(245, 158, 11, 0.3)',
                          borderRadius: 'var(--radius-md)',
                          padding: '0.75rem'
                        }}
                      >
                        <div style={{ fontSize: '0.8rem', color: 'var(--warning)', marginBottom: '0.4rem', fontWeight: 600 }}>
                          Shared across {group.length} accounts:
                        </div>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.4rem' }}>
                          {group.map((item) => (
                            <div
                              key={item.id}
                              style={{
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'space-between',
                                fontSize: '0.85rem'
                              }}
                            >
                              <span>
                                <strong>{item.title}</strong>{' '}
                                <span style={{ color: 'var(--text-muted)' }}>({item.username || 'no username'})</span>
                              </span>
                              <button
                                className="btn btn-secondary"
                                style={{ padding: '0.25rem 0.5rem', fontSize: '0.75rem' }}
                                onClick={() => {
                                  onClose();
                                  onEditItem(item);
                                }}
                              >
                                Change
                              </button>
                            </div>
                          ))}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </div>

        <div className="modal-footer">
          <button type="button" className="btn btn-secondary" onClick={onClose}>
            Close
          </button>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useRef } from 'react';
import { useVault } from '../context/VaultContext';
import { useToast } from './Toast';
import { X, Settings, Key, Download, Upload, Trash2, AlertTriangle, Shield } from './Icons';
import { evaluatePasswordStrength } from '../services/generator';

export function SettingsModal({ isOpen, onClose }) {
  const {
    autoLockMinutes,
    updateSettings,
    changeMasterPassword,
    exportEncryptedVault,
    importBackup,
    resetVault
  } = useVault();
  const { showToast } = useToast();

  const [activeTab, setActiveTab] = useState('general'); // 'general' | 'password' | 'backup' | 'danger'

  // Change password states
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [isChangingPass, setIsChangingPass] = useState(false);

  // Import states
  const [importPassword, setImportPassword] = useState('');
  const [selectedFileContent, setSelectedFileContent] = useState(null);
  const [isImporting, setIsImporting] = useState(false);
  const fileInputRef = useRef(null);

  if (!isOpen) return null;

  const handleChangePassword = async (e) => {
    e.preventDefault();
    if (!currentPassword || !newPassword) {
      showToast('Please fill in all password fields.', 'danger');
      return;
    }
    if (newPassword.length < 8) {
      showToast('New master password must be at least 8 characters.', 'danger');
      return;
    }
    if (newPassword !== confirmPassword) {
      showToast('New passwords do not match.', 'danger');
      return;
    }

    setIsChangingPass(true);
    try {
      await changeMasterPassword(currentPassword, newPassword);
      showToast('Master password changed and vault re-encrypted successfully!');
      setCurrentPassword('');
      setNewPassword('');
      setConfirmPassword('');
    } catch (err) {
      showToast('Failed to change password: ' + err.message, 'danger');
    } finally {
      setIsChangingPass(false);
    }
  };

  const handleExport = async () => {
    try {
      await exportEncryptedVault();
      showToast('Encrypted vault backup downloaded!');
    } catch (err) {
      showToast('Export failed: ' + err.message, 'danger');
    }
  };

  const handleFileChange = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      setSelectedFileContent(event.target.result);
    };
    reader.readAsText(file);
  };

  const handleImport = async (e) => {
    e.preventDefault();
    if (!selectedFileContent) {
      showToast('Please select a backup file first.', 'danger');
      return;
    }
    if (!importPassword) {
      showToast('Please enter the master password for this backup.', 'danger');
      return;
    }

    setIsImporting(true);
    try {
      const count = await importBackup(selectedFileContent, importPassword);
      showToast(`Successfully imported ${count} items!`);
      setSelectedFileContent(null);
      setImportPassword('');
      if (fileInputRef.current) fileInputRef.current.value = '';
    } catch (err) {
      showToast('Import failed: ' + err.message, 'danger');
    } finally {
      setIsImporting(false);
    }
  };

  const handleResetVault = async () => {
    const confirmed = window.confirm(
      'DANGER: Are you sure you want to permanently wipe all vault items and reset your master password? This cannot be undone!'
    );
    if (confirmed) {
      await resetVault();
      showToast('Vault has been completely reset.');
      onClose();
    }
  };

  const newPassStrength = evaluatePasswordStrength(newPassword);

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-card" onClick={(e) => e.stopPropagation()} style={{ maxWidth: '560px' }}>
        <div className="modal-header">
          <div className="modal-title">
            <Settings size={20} />
            <span>Vault Settings</span>
          </div>
          <button className="btn-icon" onClick={onClose}>
            <X size={18} />
          </button>
        </div>

        {/* Tab Navigation */}
        <div style={{ display: 'flex', borderBottom: '1px solid var(--border-color)', padding: '0 1rem', background: 'rgba(17, 24, 39, 0.4)' }}>
          {[
            { id: 'general', label: 'General' },
            { id: 'password', label: 'Master Password' },
            { id: 'backup', label: 'Backup & Restore' },
            { id: 'danger', label: 'Danger Zone' }
          ].map((tab) => (
            <button
              key={tab.id}
              className={`sidebar-item ${activeTab === tab.id ? 'active' : ''}`}
              style={{ borderRadius: '0', borderBottom: activeTab === tab.id ? '2px solid var(--primary)' : 'none', padding: '0.75rem 1rem' }}
              onClick={() => setActiveTab(tab.id)}
            >
              {tab.label}
            </button>
          ))}
        </div>

        <div className="modal-body">
          {/* General Tab */}
          {activeTab === 'general' && (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
              <div className="form-group">
                <label className="form-label">Auto-Lock Inactivity Timer</label>
                <select
                  className="form-select"
                  value={autoLockMinutes}
                  onChange={(e) => updateSettings({ autoLockMinutes: parseInt(e.target.value, 10) })}
                >
                  <option value={1}>1 minute (strict)</option>
                  <option value={5}>5 minutes</option>
                  <option value={10}>10 minutes</option>
                  <option value={15}>15 minutes (default)</option>
                  <option value={30}>30 minutes</option>
                  <option value={60}>1 hour</option>
                  <option value={0}>Never (not recommended)</option>
                </select>
                <span style={{ fontSize: '0.78rem', color: 'var(--text-muted)' }}>
                  The vault will automatically lock itself and flush decrypted keys from memory after inactivity.
                </span>
              </div>

              <div
                style={{
                  background: 'var(--bg-input)',
                  border: '1px solid var(--border-color)',
                  borderRadius: 'var(--radius-md)',
                  padding: '1rem',
                  fontSize: '0.85rem'
                }}
              >
                <div style={{ fontWeight: 600, color: 'var(--primary)', display: 'flex', alignItems: 'center', gap: '0.4rem', marginBottom: '0.35rem' }}>
                  <Shield size={16} /> Privacy & Security Guarantee
                </div>
                <p style={{ color: 'var(--text-secondary)' }}>
                  All cryptography is handled directly in your browser using the W3C Web Crypto API standard (PBKDF2 SHA-256 and AES-GCM 256-bit). Data is stored locally in IndexedDB. No external servers or analytics are ever pinged.
                </p>
              </div>
            </div>
          )}

          {/* Master Password Tab */}
          {activeTab === 'password' && (
            <form onSubmit={handleChangePassword} style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
              <div className="form-group">
                <label className="form-label">Current Master Password</label>
                <input
                  type="password"
                  className="form-input"
                  placeholder="Enter current password"
                  value={currentPassword}
                  onChange={(e) => setCurrentPassword(e.target.value)}
                  required
                />
              </div>

              <div className="form-group">
                <label className="form-label">New Master Password</label>
                <input
                  type="password"
                  className="form-input"
                  placeholder="Enter new master password"
                  value={newPassword}
                  onChange={(e) => setNewPassword(e.target.value)}
                  required
                />
                {newPassword && (
                  <div style={{ marginTop: '0.25rem' }}>
                    <div className="strength-meter">
                      <div className={`strength-bar ${newPassStrength.score >= 1 ? (newPassStrength.score === 1 ? 'weak' : newPassStrength.score === 2 ? 'medium' : 'strong') : ''}`} />
                      <div className={`strength-bar ${newPassStrength.score >= 2 ? (newPassStrength.score === 2 ? 'medium' : 'strong') : ''}`} />
                      <div className={`strength-bar ${newPassStrength.score >= 3 ? 'strong' : ''}`} />
                      <div className={`strength-bar ${newPassStrength.score >= 4 ? 'strong' : ''}`} />
                    </div>
                    <div className="strength-text" style={{ color: newPassStrength.color }}>
                      {newPassStrength.label} ({newPassStrength.bits} bits)
                    </div>
                  </div>
                )}
              </div>

              <div className="form-group">
                <label className="form-label">Confirm New Password</label>
                <input
                  type="password"
                  className="form-input"
                  placeholder="Confirm new password"
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  required
                />
              </div>

              <button
                type="submit"
                className="btn btn-primary"
                disabled={isChangingPass}
                style={{ alignSelf: 'flex-start', marginTop: '0.5rem' }}
              >
                {isChangingPass ? 'Re-encrypting Vault...' : 'Update & Re-encrypt Vault'}
              </button>
            </form>
          )}

          {/* Backup & Restore Tab */}
          {activeTab === 'backup' && (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
              <div>
                <h4 style={{ fontSize: '0.95rem', fontWeight: 600, marginBottom: '0.4rem' }}>
                  Export Encrypted Vault
                </h4>
                <p style={{ fontSize: '0.82rem', color: 'var(--text-muted)', marginBottom: '0.75rem' }}>
                  Download an encrypted `.json` file of your vault. Because it remains AES-GCM encrypted with your master password, it is safe to store in USB drives or cloud backups.
                </p>
                <button className="btn btn-secondary" onClick={handleExport}>
                  <Download size={16} /> Export Backup (.json)
                </button>
              </div>

              <hr style={{ borderColor: 'var(--border-color)' }} />

              <div>
                <h4 style={{ fontSize: '0.95rem', fontWeight: 600, marginBottom: '0.4rem' }}>
                  Import Encrypted Vault
                </h4>
                <p style={{ fontSize: '0.82rem', color: 'var(--text-muted)', marginBottom: '0.75rem' }}>
                  Restore credentials from an encrypted backup file. Items will be decrypted using the backup's master password and merged into your current vault.
                </p>

                <form onSubmit={handleImport} style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                  <input
                    type="file"
                    accept=".json"
                    ref={fileInputRef}
                    onChange={handleFileChange}
                    style={{ fontSize: '0.85rem' }}
                  />

                  {selectedFileContent && (
                    <div className="form-group">
                      <label className="form-label">Master Password of the Backup File</label>
                      <input
                        type="password"
                        className="form-input"
                        placeholder="Enter password for this backup"
                        value={importPassword}
                        onChange={(e) => setImportPassword(e.target.value)}
                        required
                      />
                    </div>
                  )}

                  <button
                    type="submit"
                    className="btn btn-primary"
                    disabled={!selectedFileContent || isImporting}
                    style={{ alignSelf: 'flex-start' }}
                  >
                    <Upload size={16} /> {isImporting ? 'Decrypting & Importing...' : 'Import Backup'}
                  </button>
                </form>
              </div>
            </div>
          )}

          {/* Danger Zone Tab */}
          {activeTab === 'danger' && (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
              <div
                style={{
                  border: '1px solid var(--danger)',
                  borderRadius: 'var(--radius-md)',
                  padding: '1.25rem',
                  background: 'var(--danger-light)'
                }}
              >
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', color: 'var(--danger)', fontWeight: 700, marginBottom: '0.5rem' }}>
                  <AlertTriangle size={20} /> Danger Zone: Factory Reset
                </div>
                <p style={{ fontSize: '0.85rem', color: 'var(--text-primary)', marginBottom: '1rem' }}>
                  Permanently delete all stored credentials, clear the master password salt, and reset IndexedDB to an empty state. There is NO way to recover your data after this step!
                </p>
                <button className="btn btn-danger" onClick={handleResetVault}>
                  <Trash2 size={16} /> Wipe Everything & Reset Vault
                </button>
              </div>
            </div>
          )}
        </div>

        <div className="modal-footer">
          <button type="button" className="btn btn-secondary" onClick={onClose}>
            Close
          </button>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { VaultProvider, useVault } from './context/VaultContext';
import { ToastProvider } from './components/Toast';
import { UnlockScreen } from './components/UnlockScreen';
import { Navbar } from './components/Navbar';
import { Sidebar } from './components/Sidebar';
import { ItemList } from './components/ItemList';
import { ItemModal } from './components/ItemModal';
import { PasswordGeneratorModal } from './components/PasswordGeneratorModal';
import { SettingsModal } from './components/SettingsModal';
import { SecurityAuditModal } from './components/SecurityAuditModal';
import { Shield } from './components/Icons';

function VaultDashboard() {
  const { vaultState, items } = useVault();

  const [activeCategory, setActiveCategory] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');

  // Modal controls
  const [isItemModalOpen, setIsItemModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [isGeneratorOpen, setIsGeneratorOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isAuditOpen, setIsAuditOpen] = useState(false);

  // Calculate counts
  const categoryCounts = useMemo(() => {
    const counts = { all: items.length, favorites: 0, logins: 0, cards: 0, notes: 0 };
    items.forEach((item) => {
      if (item.favorite) counts.favorites++;
      const cat = item.category || 'logins';
      if (counts[cat] !== undefined) counts[cat]++;
    });
    return counts;
  }, [items]);

  // Security audit count
  const auditCount = useMemo(() => {
    let weakCount = 0;
    const pwdMap = {};
    items.forEach((item) => {
      if (item.category === 'logins' && item.password) {
        if (item.password.length < 12) weakCount++;
        pwdMap[item.password] = (pwdMap[item.password] || 0) + 1;
      }
    });
    const reusedCount = Object.values(pwdMap).filter((c) => c > 1).length;
    return weakCount + reusedCount;
  }, [items]);

  if (vaultState === 'loading') {
    return (
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--bg-main)' }}>
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '1rem', color: 'var(--primary)' }}>
          <Shield size={40} className="shake" />
          <span style={{ fontSize: '1rem', color: 'var(--text-secondary)' }}>Loading offline vault...</span>
        </div>
      </div>
    );
  }

  if (vaultState === 'uninitialized' || vaultState === 'locked') {
    return <UnlockScreen />;
  }

  const handleOpenAddModal = () => {
    setEditingItem(null);
    setIsItemModalOpen(true);
  };

  const handleEditItem = (item) => {
    setEditingItem(item);
    setIsItemModalOpen(true);
  };

  return (
    <div className="app-container">
      <Navbar
        searchQuery={searchQuery}
        setSearchQuery={setSearchQuery}
        onOpenAddModal={handleOpenAddModal}
        onOpenGenerator={() => setIsGeneratorOpen(true)}
        onOpenSettings={() => setIsSettingsOpen(true)}
        onOpenAudit={() => setIsAuditOpen(true)}
        auditCount={auditCount}
      />

      <div className="main-layout">
        <Sidebar
          activeCategory={activeCategory}
          setActiveCategory={setActiveCategory}
          categoryCounts={categoryCounts}
          onOpenAudit={() => setIsAuditOpen(true)}
          auditCount={auditCount}
        />

        <ItemList
          items={items}
          activeCategory={activeCategory}
          searchQuery={searchQuery}
          onOpenAddModal={handleOpenAddModal}
          onEditItem={handleEditItem}
        />
      </div>

      {/* Modals */}
      <ItemModal
        isOpen={isItemModalOpen}
        onClose={() => setIsItemModalOpen(false)}
        editingItem={editingItem}
      />

      <PasswordGeneratorModal
        isOpen={isGeneratorOpen}
        onClose={() => setIsGeneratorOpen(false)}
      />

      <SettingsModal
        isOpen={isSettingsOpen}
        onClose={() => setIsSettingsOpen(false)}
      />

      <SecurityAuditModal
        isOpen={isAuditOpen}
        onClose={() => setIsAuditOpen(false)}
        items={items}
        onEditItem={handleEditItem}
      />
    </div>
  );
}

export default function App() {
  return (
    <ToastProvider>
      <VaultProvider>
        <VaultDashboard />
      </VaultProvider>
    </ToastProvider>
  );
}

