/**
 * Cryptographic operations using the browser's native Web Crypto API.
 * PBKDF2 (100,000 iterations, SHA-256) + AES-GCM 256-bit.
 * Zero external dependencies.
 */

export const CANARY_SECRET = '__OFFLINE_VAULT_CANARY_OK__';
export const PBKDF2_ITERATIONS = 100000;

export function bufferToBase64(buffer) {
  let binary = '';
  const bytes = new Uint8Array(buffer);
  for (let i = 0; i < bytes.byteLength; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

export function base64ToBuffer(base64) {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

export function generateSalt(length = 16) {
  const salt = new Uint8Array(length);
  crypto.getRandomValues(salt);
  return bufferToBase64(salt);
}

export async function deriveMasterKey(masterPassword, saltBase64) {
  const encoder = new TextEncoder();
  const passwordKey = await crypto.subtle.importKey(
    'raw',
    encoder.encode(masterPassword),
    { name: 'PBKDF2' },
    false,
    ['deriveKey']
  );

  const salt = base64ToBuffer(saltBase64);

  return await crypto.subtle.deriveKey(
    {
      name: 'PBKDF2',
      salt,
      iterations: PBKDF2_ITERATIONS,
      hash: 'SHA-256'
    },
    passwordKey,
    {
      name: 'AES-GCM',
      length: 256
    },
    true, // exportable for session cache in service worker if needed
    ['encrypt', 'decrypt']
  );
}

export async function encryptPayload(data, key) {
  const encoder = new TextEncoder();
  const iv = new Uint8Array(12);
  crypto.getRandomValues(iv);

  const encryptedBuffer = await crypto.subtle.encrypt(
    { name: 'AES-GCM', iv },
    key,
    encoder.encode(JSON.stringify(data))
  );

  return {
    ciphertext: bufferToBase64(encryptedBuffer),
    iv: bufferToBase64(iv)
  };
}

export async function decryptPayload(encryptedObj, key) {
  const ivBuffer = base64ToBuffer(encryptedObj.iv);
  const dataBuffer = base64ToBuffer(encryptedObj.ciphertext);

  const decryptedBuffer = await crypto.subtle.decrypt(
    { name: 'AES-GCM', iv: ivBuffer },
    key,
    dataBuffer
  );

  const decoder = new TextDecoder();
  return JSON.parse(decoder.decode(decryptedBuffer));
}

export function generateSecurePassword({
  length = 20,
  useLower = true,
  useUpper = true,
  useNumbers = true,
  useSymbols = true,
  avoidAmbiguous = false
} = {}) {
  let lower = 'abcdefghijklmnopqrstuvwxyz';
  let upper = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  let nums = '0123456789';
  let syms = '!@#$%^&*()_+-=[]{}|;:,.<>?';

  if (avoidAmbiguous) {
    lower = lower.replace(/[il1]/g, '');
    upper = upper.replace(/[IO]/g, '');
    nums = nums.replace(/[01]/g, '');
    syms = syms.replace(/[{}[\]()/\\'"`~,;:.<>]/g, '');
  }

  let pool = '';
  const guaranteed = [];
  const getRand = (max) => {
    const arr = new Uint32Array(1);
    crypto.getRandomValues(arr);
    return arr[0] % max;
  };

  if (useLower) { pool += lower; guaranteed.push(lower[getRand(lower.length)]); }
  if (useUpper) { pool += upper; guaranteed.push(upper[getRand(upper.length)]); }
  if (useNumbers) { pool += nums; guaranteed.push(nums[getRand(nums.length)]); }
  if (useSymbols) { pool += syms; guaranteed.push(syms[getRand(syms.length)]); }
  if (!pool) { pool = lower; guaranteed.push(lower[getRand(lower.length)]); }

  const res = [...guaranteed];
  while (res.length < length) res.push(pool[getRand(pool.length)]);

  for (let i = res.length - 1; i > 0; i--) {
    const j = getRand(i + 1);
    [res[i], res[j]] = [res[j], res[i]];
  }

  return res.join('');
}

export function evaluateStrength(pwd) {
  if (!pwd) return { score: 0, label: 'Empty', color: '#64748b', bits: 0 };
  let pool = 0;
  if (/[a-z]/.test(pwd)) pool += 26;
  if (/[A-Z]/.test(pwd)) pool += 26;
  if (/[0-9]/.test(pwd)) pool += 10;
  if (/[^a-zA-Z0-9]/.test(pwd)) pool += 32;

  const bits = Math.floor(pwd.length * Math.log2(pool || 1));
  if (pwd.length < 8 || bits < 40) return { score: 1, label: 'Weak', color: '#ef4444', bits };
  if (pwd.length < 12 || bits < 60) return { score: 2, label: 'Fair', color: '#f59e0b', bits };
  if (pwd.length < 16 || bits < 80) return { score: 3, label: 'Strong', color: '#10b981', bits };
  return { score: 4, label: 'Very Strong', color: '#34d399', bits };
}

/**
 * chrome.storage.local wrapper for local encrypted storage.
 * Zero external calls.
 */

export async function getStoredMeta() {
  const result = await chrome.storage.local.get(['vault_meta']);
  return result.vault_meta || null;
}

export async function setStoredMeta(meta) {
  await chrome.storage.local.set({ vault_meta: meta });
}

export async function getStoredItems() {
  const result = await chrome.storage.local.get(['vault_items']);
  return result.vault_items || [];
}

export async function saveStoredItem(item) {
  const items = await getStoredItems();
  const index = items.findIndex(i => i.id === item.id);
  if (index >= 0) {
    items[index] = item;
  } else {
    items.unshift(item);
  }
  await chrome.storage.local.set({ vault_items: items });
}

export async function deleteStoredItem(id) {
  const items = await getStoredItems();
  const filtered = items.filter(i => i.id !== id);
  await chrome.storage.local.set({ vault_items: filtered });
}

export async function clearAllStoredData() {
  await chrome.storage.local.clear();
}

/**
 * Offline Vault - Background Service Worker
 * Coordinates in-memory crypto key, domain matching, and in-page auto-fill.
 */

import { getStoredMeta, getStoredItems } from './storage.js';
import { decryptPayload } from './crypto.js';

let sessionMasterKey = null;
let autoLockTimer = null;
let autoLockMinutes = 15;

// Generate and set action icon dynamically using OffscreenCanvas
function generateBadgeIcon() {
  try {
    const canvas = new OffscreenCanvas(32, 32);
    const ctx = canvas.getContext('2d');

    // Background circle
    ctx.fillStyle = '#090d16';
    ctx.beginPath();
    ctx.arc(16, 16, 15, 0, Math.PI * 2);
    ctx.fill();

    // Shield border
    ctx.strokeStyle = '#10b981';
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.moveTo(16, 6);
    ctx.lineTo(24, 9);
    ctx.lineTo(24, 16);
    ctx.quadraticCurveTo(24, 25, 16, 27);
    ctx.quadraticCurveTo(8, 25, 8, 16);
    ctx.lineTo(8, 9);
    ctx.closePath();
    ctx.stroke();

    // Checkmark inside shield
    ctx.strokeStyle = '#34d399';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(12, 16);
    ctx.lineTo(15, 19);
    ctx.lineTo(20, 13);
    ctx.stroke();

    const imageData = ctx.getImageData(0, 0, 32, 32);
    chrome.action.setIcon({ imageData });
  } catch (err) {
    console.log('Icon generation fallback');
  }
}

chrome.runtime.onInstalled.addListener(() => {
  generateBadgeIcon();
});

chrome.runtime.onStartup.addListener(() => {
  generateBadgeIcon();
});

// Domain normalization (e.g., "https://github.com/login" -> "github.com")
function extractDomain(url) {
  if (!url) return '';
  try {
    const parsed = new URL(url.startsWith('http') ? url : `https://${url}`);
    return parsed.hostname.replace(/^www\./, '').toLowerCase();
  } catch (e) {
    return url.toLowerCase();
  }
}

function resetInactivityTimer() {
  if (autoLockTimer) clearTimeout(autoLockTimer);
  if (autoLockMinutes > 0 && sessionMasterKey) {
    autoLockTimer = setTimeout(() => {
      sessionMasterKey = null;
      console.log('Vault auto-locked due to inactivity.');
    }, autoLockMinutes * 60 * 1000);
  }
}

// Handle messages from content script and popup
chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  resetInactivityTimer();

  if (message.type === 'GET_VAULT_STATUS') {
    getStoredMeta().then(meta => {
      sendResponse({
        isInitialized: !!(meta && meta.salt && meta.canary),
        isUnlocked: !!sessionMasterKey
      });
    });
    return true; // asynchronous
  }

  if (message.type === 'SET_SESSION_KEY') {
    sessionMasterKey = message.key;
    if (message.autoLockMinutes) {
      autoLockMinutes = message.autoLockMinutes;
    }
    resetInactivityTimer();
    sendResponse({ success: true });
    return true;
  }

  if (message.type === 'GET_SESSION_KEY') {
    sendResponse({ key: sessionMasterKey });
    return true;
  }

  if (message.type === 'LOCK_VAULT') {
    sessionMasterKey = null;
    if (autoLockTimer) clearTimeout(autoLockTimer);
    sendResponse({ success: true });
    return true;
  }

  // Request from content script on a web page (e.g. github.com)
  if (message.type === 'GET_MATCHING_CREDENTIALS') {
    if (!sessionMasterKey) {
      sendResponse({ isUnlocked: false, credentials: [] });
      return true;
    }

    const currentDomain = extractDomain(message.url);

    getStoredItems().then(async (encryptedItems) => {
      const matches = [];

      for (const item of encryptedItems) {
        if (item.category !== 'logins') continue;

        try {
          const secret = await decryptPayload(
            { ciphertext: item.ciphertext, iv: item.iv },
            sessionMasterKey
          );

          const itemDomain = extractDomain(secret.url || secret.title);

          // Check if domain matches (e.g. github.com matches github.com or github.com/login)
          if (
            (itemDomain && currentDomain.includes(itemDomain)) ||
            (itemDomain && itemDomain.includes(currentDomain)) ||
            (secret.title && currentDomain.includes(secret.title.toLowerCase()))
          ) {
            matches.push({
              id: item.id,
              title: secret.title,
              username: secret.username,
              password: secret.password
            });
          }
        } catch (e) {
          console.error('Failed to decrypt record', e);
        }
      }

      sendResponse({ isUnlocked: true, credentials: matches });
    });

    return true; // async
  }
});

