        </p>
        <form id="import-form" style="display:flex;flex-direction:column;gap:0.75rem;">
          <input type="file" id="import-file" accept=".json" required />
          <div>
            <label style="font-size:11px;color:var(--text-muted);">MASTER PASSWORD OF BACKUP</label>
            <input type="password" id="import-pass" class="form-input" placeholder="Password used to export" required />
          </div>
          <div style="display:flex;justify-content:flex-end;gap:0.5rem;margin-top:0.5rem;">
            <button type="button" class="btn btn-secondary" id="import-cancel">Cancel</button>
            <button type="submit" class="btn btn-primary">Decrypt & Import</button>
          </div>
        </form>
      </div>
    </div>
  `;

  document.getElementById('import-cancel').onclick = () => { slot.innerHTML = ''; };
  document.getElementById('import-modal-overlay').onclick = () => { slot.innerHTML = ''; };

  document.getElementById('import-form').onsubmit = async (e) => {
    e.preventDefault();
    const file = document.getElementById('import-file').files[0];
    const pass = document.getElementById('import-pass').value;
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (evt) => {
      try {
        const backup = JSON.parse(evt.target.result);
        if (!backup.salt || !backup.canary || !Array.isArray(backup.items)) {
          throw new Error('Invalid backup format');
        }

        const backupKey = await deriveMasterKey(pass, backup.salt);
        const test = await decryptPayload(backup.canary, backupKey);
        if (!test || test.canary !== CANARY_SECRET) throw new Error('Incorrect master password');

        let count = 0;
        for (const bItem of backup.items) {
          try {
            const secret = await decryptPayload({ ciphertext: bItem.ciphertext, iv: bItem.iv }, backupKey);
            const reEncrypted = await encryptPayload(secret, masterKey);
            const id = bItem.id || Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
            await saveStoredItem({
              id,
              category: bItem.category || 'logins',
              ciphertext: reEncrypted.ciphertext,
              iv: reEncrypted.iv,
              updatedAt: new Date().toISOString()
            });
            count++;
          } catch (err) {
            console.error(err);
          }
        }

        slot.innerHTML = '';
        await loadItems();
        renderDashboard();
        showToast(`Successfully imported ${count} items into the extension!`);
      } catch (err) {
        showToast('Import failed: ' + err.message);
      }
    };
    reader.readAsText(file);
  };
}

